def locations_from_text(apps, schema_editor):
    """Each old free-text batch location becomes a real stock location; 'Main Pharmacy' is the dispensing one."""
    StockBatch, StockLocation = apps.get_model('hospital', 'StockBatch'), apps.get_model('hospital', 'StockLocation')
    for name in StockBatch.objects.values_list('location', flat=True).distinct():
        name = (name or 'Main Pharmacy').strip() or 'Main Pharmacy'
        dispensing = name.lower() == 'main pharmacy'
        loc, _ = StockLocation.objects.get_or_create(name=name, defaults={'kind': 'pharmacy' if dispensing else 'store', 'is_dispensing': dispensing})
        StockBatch.objects.filter(location=name).update(store=loc)
    if not StockLocation.objects.filter(is_dispensing=True).exists():
        StockLocation.objects.get_or_create(name='Main Pharmacy', defaults={'kind': 'pharmacy', 'is_dispensing': True})


def ledger_start(apps, schema_editor):
    """Give stock that existed before the ledger a starting entry, so every stock card balances from day one."""
    StockBatch, StockMovement = apps.get_model('hospital', 'StockBatch'), apps.get_model('hospital', 'StockMovement')
    User = apps.get_model(*settings.AUTH_USER_MODEL.split('.'))
    actor = User.objects.filter(is_superuser=True).order_by('pk').first() or User.objects.order_by('pk').first()
    if not actor:
        return
    running = {}
    for b in StockBatch.objects.filter(quantity__gt=0).order_by('medication_id', 'store_id', 'expiry'):
        k = (b.medication_id, b.store_id); running[k] = running.get(k, 0) + b.quantity
        StockMovement.objects.create(medication_id=b.medication_id, batch=b, location_id=b.store_id, kind='opening', quantity=b.quantity,
                                     balance_after=running[k], unit_cost=b.unit_cost, reference='LEDGER-START',
                                     note='Balance when the stock ledger started', actor=actor)


